import re, html as h, json

# Parse CVF index: titles -> pdf links
idx = open('cvf_index.html', encoding='utf-8', errors='ignore').read()
# entries look like: <dt class="ptitle"><a href="/content/ICCV2025/html/...">Title</a></dt> ... <a href="/content/ICCV2025/papers/....pdf">pdf</a>
entries = re.findall(r'<dt class="ptitle"><a href="([^"]+)">([^<]+)</a></dt>(.*?)</dd>', idx, re.S)
print("entries:", len(entries))
mapping = {}
for html_url, title, rest in entries:
    t = h.unescape(title).strip()
    m = re.search(r'href="([^"]+\.pdf)"', rest)
    pdf = m.group(1) if m else None
    mapping[t] = {'html': html_url, 'pdf': pdf}

# Load oral titles
oral_html = open('oral_page.html', encoding='utf-8', errors='ignore').read()
cards = re.findall(r'<a href="/virtual/2025/oral/(\d+)">\s*<h[^>]*>(.*?)</h', oral_html, re.S)
seen=set(); orals=[]
for pid, title in cards:
    t = h.unescape(re.sub(r'\s+',' ',title)).strip()
    if pid not in seen and t:
        seen.add(pid); orals.append({'id':pid,'title':t})
print("orals:", len(orals))

def norm(s):
    return re.sub(r'[^a-z0-9]+',' ', s.lower()).strip()

# Build normalized lookup
norm_map = {norm(k): k for k in mapping}
matched, unmatched = [], []
for o in orals:
    n = norm(o['title'])
    if n in norm_map:
        k = norm_map[n]
        o2 = dict(o); o2.update(mapping[k]); o2['cvf_title']=k
        matched.append(o2)
    else:
        unmatched.append(o)
print("matched:", len(matched), "unmatched:", len(unmatched))
for u in unmatched: print("UNMATCHED:", u['title'])
json.dump(matched, open('orals_matched.json','w'), indent=1)
json.dump(unmatched, open('orals_unmatched.json','w'), indent=1)
EOF

