import json, subprocess, os, concurrent.futures
papers = json.load(open('orals_matched.json'))
def dl(p):
    url = 'https://openaccess.thecvf.com' + p['pdf']
    fn = 'pdfs/%s.pdf' % p['id']
    if os.path.exists(fn) and os.path.getsize(fn) > 20000:
        return (p['id'], 'cached')
    r = subprocess.run(['curl','-s','-L','--retry','3','-A','Mozilla/5.0','-o',fn,url], capture_output=True)
    sz = os.path.getsize(fn) if os.path.exists(fn) else 0
    return (p['id'], sz)
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as ex:
    for pid, res in ex.map(dl, papers):
        print(pid, res)
