import fitz, json, re
papers = json.load(open('orals_matched.json'))
texts = {}
for p in papers:
    doc = fitz.open('pdfs/%s.pdf' % p['id'])
    t = doc[0].get_text()
    texts[p['id']] = t
    doc.close()
json.dump(texts, open('first_pages.json','w'))
# Show which contain SJTU or FDU anywhere on first page
for p in papers:
    t = texts[p['id']]
    hits = []
    if re.search(r'Shanghai\s+Jiao\s+Tong', t, re.I): hits.append('SJTU')
    if re.search(r'Fudan\s+University', t, re.I): hits.append('FDU')
    if hits:
        print(p['id'], hits, '|', p['title'][:70])
