import json, re
texts = json.load(open('first_pages.json'))
papers = json.load(open('orals_matched.json'))
id2title = {p['id']: p['title'] for p in papers}
# thorough variants
pats = {'SJTU': [r'Shanghai\s*Jiao\s*Tong', r'SJTU', r'Jiao\s*Tong\s*University'],
        'FDU': [r'Fudan', r'Fudan\s*University']}
for pid, t in texts.items():
    for k, ps in pats.items():
        for pat in ps:
            if re.search(pat, t, re.I):
                print(pid, k, '->', id2title[pid][:60], '| pattern:', pat)
                break
